  function calendarView(){
    const [year,month]=monthView.split('-').map(Number),first=new Date(Date.UTC(year,month-1,1,12));
    const offset=first.getUTCDay(),count=new Date(Date.UTC(year,month,0)).getUTCDate();
    const cellCount=Math.ceil((offset+count)/7)*7,events=allEvents(),today=dateKey();
    const weeks=Array.from({length:cellCount/7},(_,week)=>{
      const days=Array.from({length:7},(_,column)=>{const iso=plusDays(`${monthView}-01`,week*7+column-offset);return iso.startsWith(monthView)?iso:null});
      const occupied=[],segments=[];
      events.filter(e=>days.some(iso=>iso&&covers(e,iso))).sort((a,b)=>a.start.localeCompare(b.start)||((b.end||b.start).localeCompare(a.end||a.start))).forEach(e=>{
        const columns=days.map((iso,i)=>iso&&covers(e,iso)?i:-1).filter(i=>i>=0),start=columns[0],end=columns.at(-1);
        let lane=occupied.findIndex(ranges=>ranges.every(([a,b])=>end<a||start>b));
        if(lane<0){lane=occupied.length;occupied.push([])}
        occupied[lane].push([start,end]);segments.push({event:e,start,end,lane,continuesBefore:e.start<days[start],continuesAfter:(e.end||e.start)>days[end]});
      });
      const cells=days.map(iso=>{if(!iso)return'<div class="calendar-cell outside" aria-hidden="true"></div>';
        const due=state.homework.filter(h=>dateKey(new Date(h.due))===iso);
        return`<div class="calendar-cell ${iso===today?'today':''}"><span class="calendar-date">${Number(iso.slice(-2))}</span><div class="calendar-event-space" style="height:${occupied.length*24}px"></div>${due.slice(0,2).map(h=>`<button class="calendar-due ${h.complete?'completed':''}" data-action="hw-edit" data-id="${esc(h.id)}" title="${esc(h.title)} due">${icon(h.complete?'check':'calendar')}${esc(h.title)} due</button>`).join('')}${due.length>2?`<div class="calendar-more">+${due.length-2} due</div>`:''}</div>`;
      }).join('');
      const bands=segments.map(({event,start,end,lane,continuesBefore,continuesAfter})=>`<button class="calendar-band ${continuesBefore?'continues-before':''} ${continuesAfter?'continues-after':''}" style="grid-column:${start+1}/${end+2};grid-row:${lane+1};background:${hex(event.color)?event.color:'#292a2c'};color:${hex(event.color)?colorText(event.color):'#fff'}" data-action="event-edit" data-id="${esc(event.id)}" title="${esc(event.title)}">${esc(event.title)}</button>`).join('');
      return`<div class="calendar-week">${cells}<div class="calendar-band-layer" style="grid-template-rows:repeat(${occupied.length||1},24px)">${bands}</div></div>`;
    }).join('');
    const monthTitle=new Intl.DateTimeFormat('en-US',{timeZone:'UTC',month:'long',year:'numeric'}).format(first);
    return header(monthTitle,`Today is ${new Intl.DateTimeFormat('en-US',{timeZone:TZ,dateStyle:'full'}).format(new Date())}`,`<button class="btn icon-only" data-action="calendar-refresh" aria-label="Refresh school calendar">${icon('sync')}</button><button class="btn icon-only" data-action="month-prev" aria-label="Previous month">‹</button><button class="btn icon-only" data-action="month-today" aria-label="Jump to today">⌖</button><button class="btn icon-only" data-action="month-next" aria-label="Next month">›</button><button class="btn primary" data-action="event-new">${icon('plus')}Add</button><a class="btn" href="https://kis.ac/school-calendar/" target="_blank" rel="noopener noreferrer">KIS</a>`)+`<section class="card calendar-card"><div class="calendar-weekdays">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<span class="calendar-label">${d}</span>`).join('')}</div><div class="calendar-weeks">${weeks}</div></section>`;
  }
  function colorText(s){const v=s.slice(1),lum=.2126*parseInt(v.slice(0,2),16)+.7152*parseInt(v.slice(2,4),16)+.0722*parseInt(v.slice(4,6),16);return lum>145?'#202124':'#fff'}
