  function showDay(){const iso=dateKey(),list=classesOn(iso);modal(`Today · ${dateLabel(iso)}`,rotationAt(iso)?`${rotationAt(iso)} Day`:'No school',list.length?`<div class="schedule-list">${list.map(c=>`<div class="class-row"><div class="class-time"><strong>${esc(c.start)}</strong>${esc(c.end)}</div><div class="class-accent" style="background:${hex(c.color)?c.color:'#27282a'}"></div><div><div class="class-name">${esc(c.subject)}</div><div class="class-detail">${esc([c.teacher,c.room].filter(Boolean).join(' · '))}</div></div></div>`).join('')}</div>`:empty('No classes scheduled today.'))}
  function parseSet(text,source){const rows=[];for(const obj of text.match(/\{[^{}]{0,1000}\}/g)||[]){const f={};for(const m of obj.matchAll(/['"]?(type|start|end|name|color|id)['"]?\s*:\s*(['"])(.*?)\2/g))f[m[1]]=m[3];const start=validDate(f.start),end=validDate(f.end||f.start);if(!start||!end||end<start||!['break','half','info','late'].includes(f.type)||!f.name)continue;rows.push({id:`remote:${source}:${f.id||`${f.type}:${start}:${end}:${f.name}`}`,title:f.name,type:f.type,start,end:end===start?'':end,color:hex(f.color)?f.color:'#303234',note:'',remote:true})}return rows}
  async function refreshCalendar(silent=false){try{const sources=['global',state.division.toLowerCase()],result=await Promise.all(sources.map(async source=>{const r=await fetch(`https://kisj.space/${source}.set`,{cache:'no-store'});if(!r.ok)throw Error(`${source}.set: HTTP ${r.status}`);return parseSet(await r.text(),source)}));state.remoteEvents=result.flat();state.remoteUpdated=new Date().toISOString();save();if(page==='calendar'||page==='today')render();if(!silent)toast('School calendar updated.')}catch(e){if(!silent)toast(`Calendar update failed: ${e.message}. Saved dates are still shown.`)}}
  let menuWorkerReady;
